private AbstractCompiler compiler;
private NodeTraversal t;
private Node n;
private Node parent;

@Before
public void setUp() {
  compiler = mock(AbstractCompiler.class);
  checkSideEffects = new CheckSideEffects(compiler, CheckLevel.WARNING, true);
  t = mock(NodeTraversal.class);
  n = mock(Node.class);
  parent = mock(Node.class);
}

@Test
public void testVisitWhenNodeIsEmpty() {
  when(n.isEmpty()).thenReturn(true);
  checkSideEffects.visit(t, n, parent);
  verify(t, never()).makeError(any(Node.class), any(CheckLevel.class), any(DiagnosticType.class), anyString());
}

@Test
public void testVisitWhenNodeIsComma() {
  when(n.isComma()).thenReturn(true);
  checkSideEffects.visit(t, n, parent);
  verify(t, never()).makeError(any(Node.class), any(CheckLevel.class), any(DiagnosticType.class), anyString());
}

@Test

public void testVisitWhenParentIsNull() {
  when(parent).thenReturn(null);
  checkSideEffects.visit(t, n, parent);
  verify(t, never()).makeError(any(Node.class), any(CheckLevel.class), any(DiagnosticType.class), anyString());
}

@Test
public void testVisitWhenNodeIsExprResult() {
  when(n.isExprResult()).thenReturn(true);
  checkSideEffects.visit(t, n, parent);
  verify(t, never()).makeError(any(Node.class), any(CheckLevel.class), any(DiagnosticType.class), anyString());
}

@Test
public void testVisitWhenNodeIsBlock() {
  when(n.isBlock()).thenReturn(true);
  checkSideEffects.visit(t, n, parent);
  verify(t, never()).makeError(any(Node.class), any(CheckLevel.class), any(DiagnosticType.class), anyString());
}

@Test
public void testVisitWhenNodeIsQualifiedNameWithJSDocInfo() {
  when(n.isQualifiedName()).thenReturn(true);
  JSDocInfoBuilder builder = new JSDocInfoBuilder();
  builder.addJSDocInfo(mock(JSDocInfo.class));
  when(n.getJSDocInfo()).thenReturn(builder.build());
  checkSideEffects.visit(t, n, parent);
  verify(t, never()).makeError(any(Node.class), any(CheckLevel.class), any(DiagnosticType.class), anyString());
}

@Test
public void testVisitWhenNodeIsStringAndNotUsed() {
  when(n.isString()).thenReturn(true);
  boolean isResultUsed = false;
  boolean isSimpleOp = false;
  when(NodeUtil.isExpressionResultUsed(n)).thenReturn(isResultUsed);
  when(NodeUtil.isSimpleOperatorType(n.getType())).thenReturn(isSimpleOp);
  when(NodeUtil.mayHaveSideEffects(n, any(AbstractCompiler.class))).thenReturn(false);
  checkSideEffects.visit(t, n, parent);
  verify(t).makeError(n, eq(checkSideEffects.level), eq(CheckSideEffects.USELESS_CODE_ERROR), "Is there a missing '+' on the previous line?");
}

@Test
public void testVisitWhenNodeIsSimpleOpAndNotUsed() {
  when(n.isString()).thenReturn(false);
  boolean isResultUsed = false;
  boolean isSimpleOp = true;
  when(NodeUtil.isExpressionResultUsed(n)).thenReturn(isResultUsed);
  when(NodeUtil.isSimpleOperatorType(n.getType())).thenReturn(isSimpleOp);
  when(NodeUtil.mayHaveSideEffects(n, any(AbstractCompiler.class))).thenReturn(false);
  checkSideEffects.visit(t, n, parent);
  verify(t).makeError(n, eq(checkSideEffects.level), eq(CheckSideEffects.USELESS_CODE_ERROR), "The result of the '" + Token.name(n.getType()).toLowerCase() + "' operator is not being used.");
}

@Test
public void testVisitWhenNodeIsNotSimpleOpAndNotUsedButMayHaveSideEffects() {
  when(n.isString()).thenReturn(false);
  boolean isResultUsed = false;
  boolean isSimpleOp = false;
  when(NodeUtil.isExpressionResultUsed(n)).thenReturn(isResultUsed);
  when(NodeUtil.isSimpleOperatorType(n.getType())).thenReturn(isSimpleOp);
  when(NodeUtil.mayHaveSideEffects(n, any(AbstractCompiler.class))).thenReturn(true);
  checkSideEffects.visit(t, n, parent);
